const body = $input.first().json.body || $input.first().json;
const question = (body.question || '').trim();
const language = (body.language || 'de').trim();
if (!question) return [{ json: { valid: false, error: 'Bitte stellen Sie eine Frage.' } }];
if (question.length > 500) return [{ json: { valid: false, error: 'Frage zu lang (max. 500 Zeichen).' } }];
return [{ json: { valid: true, question, language } }];

const searchResults = $input.first().json;
const validated = $('Eingabe validieren').first().json;
const question = validated.question;
const language = validated.language;

const matches = Array.isArray(searchResults) ? searchResults : [];
const context = matches.length > 0
  ? matches.map((m, i) => '[' + (i+1) + '] (Quelle: ' + (m.source || 'FAQ') + ')\n' + m.content).join('\n\n')
  : null;
const sources = [...new Set(matches.map(m => m.source).filter(Boolean))];
const maxSimilarity = matches.length > 0 ? Math.max(...matches.map(m => m.similarity || 0)) : 0;
const isDE = language === 'de';

const systemPrompt = isDE
  ? 'Du bist ein hilfreicher FAQ-Assistent f\u00fcr Leinss Consulting. Beantworte Fragen NUR basierend auf dem bereitgestellten Kontext. Antworte immer auf Deutsch. Gib EXAKT dieses JSON zur\u00fcck: {"answer": "...", "sources": [...], "confidence": 0.0, "escalate": false, "escalation_reason": null}'
  : 'You are a helpful FAQ assistant for Leinss Consulting. Answer questions ONLY based on the provided context. Respond in English. Return EXACTLY this JSON: {"answer": "...", "sources": [...], "confidence": 0.0, "escalate": false, "escalation_reason": null}';

const contextBlock = context
  ? (isDE ? 'Wissensbank-Kontext:\n\n' : 'Knowledge base context:\n\n') + context
  : (isDE ? 'KEIN KONTEXT GEFUNDEN. Teile mit, dass du keine Informationen zu dieser Frage hast, und empfehle direkte Kontaktaufnahme.' : 'NO CONTEXT FOUND. Politely say you have no information about this question and suggest direct contact.');

const kimiRequest = {
  model: 'kimi-k2.5',
  max_tokens: 1024,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: contextBlock + '\n\n' + (isDE ? 'Frage: ' : 'Question: ') + question }
  ]
};

return [{ json: { kimiRequest, question, language, sources, maxSimilarity, hasContext: matches.length > 0 } }];

const meta = $('Anfrage aufbauen').first().json;
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;
if (!content) throw new Error('Kimi returned empty response');

let data;
try {
  data = JSON.parse(content);
} catch {
  const match = content.match(/```(?:json)?\s*([\s\S]+?)```/);
  if (!match) {
    const jsonMatch = content.match(/\{[\s\S]+\}/);
    if (!jsonMatch) throw new Error('Could not parse JSON from Kimi response: ' + content.substring(0, 200));
    data = JSON.parse(jsonMatch[0]);
  } else {
    data = JSON.parse(match[1]);
  }
}

const simConf = meta.hasContext ? Math.min(meta.maxSimilarity, 1.0) : 0.1;
const finalConf = parseFloat(Math.max(
  Math.min(data.confidence || 0.5, simConf + 0.1),
  meta.hasContext ? 0.3 : 0.1
).toFixed(2));

return [{
  json: {
    answer: data.answer,
    sources: data.sources || meta.sources || [],
    confidence: finalConf,
    escalate: data.escalate === true || finalConf < 0.5 || !meta.hasContext,
    escalation_reason: data.escalation_reason || null
  }
}];
